const COIL_T = 0.09, HOLD_T = 0.07;
const lungeOf = (p, s) => { const o = s === 'L' ? 'R' : 'L'; return { ...p, body: 0.22, bodyY: -0.2, ['hip' + s]: -1.0, ['knee' + s]: 1.0, ['hip' + o]: 0.6, ['knee' + o]: 0.1 }; };
const punch = (clip, s, coil = COIL_T) => { const o = s === 'L' ? 'R' : 'L', [k0, k1, k2] = clip.keys, hit = lungeOf(k1.p, s), wound = { ...k0.p, body: -0.1, bodyY: -0.12, ['sh' + s]: { x: 0.5, z: s === 'L' ? -0.35 : 0.35 }, ['el' + s]: -2.2, ['hip' + s]: -0.35, ['knee' + s]: 0.7, ['hip' + o]: 0.1, ['knee' + o]: 0.55 }; return { keys: [key(0, wound), key(coil, wound), key(coil + k1.t, hit, 'snap'), key(coil + k1.t + HOLD_T, hit), key(coil + k2.t + 0.06, k2.p, 'out')] }; };
