const FOE_JAB = (() => { const [k0, k1, k2] = CLIPS.jabR.keys, hit = lungeOf(k1.p, 'R'); return { keys: [key(0, k0.p), key(k1.t, hit, 'snap'), key(k1.t + HOLD_T, hit), key(k2.t, k2.p, 'out')] }; })();
